{
  "items": [
    {
      "title": "Eurostat – Expenditure on Social Benefits by Function (ESSPROS)",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/spr_exp_func/default/table",
      "justification": "One of the most relevant datasets for analyzing social welfare policy in Germany during the 2020s. Provides annual social protection expenditure data, including 2020–2025, categorized by unemployment, healthcare, disability, old-age pensions, family benefits, housing, and social exclusion. Useful for evaluating changes in welfare spending, identifying policy priorities, and comparing Germany with other European countries."
    },
    {
      "title": "German Federal Employment Agency – Basic Income Support for Jobseekers (Bürgergeld)",
      "url_or_doi": "https://data.gov.de/suche/daten/grundsicherung-fur-arbeitsuchende-burgergeld",
      "justification": "Official German administrative dataset covering recipients of unemployment-related basic income support, including Bürgergeld, introduced in January 2023. Contains longitudinal statistics on benefit recipients, household benefit units, and demographic characteristics. Data are available at national, federal-state, and district levels. Particularly valuable for studying German unemployment assistance reforms, welfare eligibility, and changes in benefit dependency during the 2020s. Includes downloadable CSV resources."
    },
    {
      "title": "Eurostat – Expenditure on Social Protection by Type of Expenditure",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/spr_exp_type/default/table",
      "justification": "Provides annual social protection expenditure statistics for Germany, including the period 2020–2024. Distinguishes social benefits, administrative expenditures, and other spending. Useful for assessing the financial structure of Germany's welfare system and tracking changes in public and private social protection expenditure during the COVID-19 pandemic and subsequent policy reforms."
    },
    {
      "title": "German Socio-Economic Panel (SOEP-Core v41) – 1984–2024",
      "url_or_doi": "https://www.diw.de/en/diw_01.c.997315.en/edition/soep-core_v41r__data_1984-2024__remote_edition.html",
      "justification": "Major longitudinal household survey conducted by the German Institute for Economic Research (DIW Berlin). Includes observations through 2024 and covers household income, employment, social transfers, poverty, living conditions, and socioeconomic inequality. Particularly useful for evaluating how German social welfare policies affect households, including low-income families, unemployed individuals, and pensioners. Its longitudinal design supports analysis of welfare outcomes before and after policy changes. Research data access is subject to applicable conditions."
    },
    {
      "title": "Eurostat – Social Protection Expenditure per Inhabitant",
      "url_or_doi": "https://doi.org/10.2908/tps00100",
      "justification": "Annual dataset measuring social protection expenditure per inhabitant in purchasing power standards (PPS). Includes German observations from 2020–2024. Particularly useful for examining trends in welfare spending per capita and comparing the relative generosity of Germany's social protection system with other European countries while accounting for differences in purchasing power."
    },
    {
      "title": "Eurostat – Social Benefits by Function as a Percentage of Total Benefits",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/bookmark/32198329-87ca-48c7-9828-71d1d21e12fd?lang=en",
      "justification": "Provides data on the distribution of social benefits across different welfare functions, with coverage extending into the 2020s. Enables researchers to examine how Germany allocates social protection resources among healthcare, pensions, unemployment, disability, housing, and family support. Especially relevant for investigating changes in welfare priorities and the composition of social spending during the decade."
    },
    {
      "title": "Eurostat – Expenditure on Sickness and Healthcare Benefits",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/page/SPR_EXP_FSI",
      "justification": "Detailed dataset covering social protection expenditure associated with sickness and healthcare. Includes distinctions between means-tested and non-means-tested benefits, cash benefits, and benefits provided in kind. Relevant for analyzing Germany's healthcare-related welfare policies during the 2020s, including the financial implications of the COVID-19 pandemic and changes in social protection arrangements."
    },
    {
      "title": "Institute for Employment Research (IAB) – Sample of Integrated Welfare Benefit Biographies (SIG), 2007–2023",
      "url_or_doi": "https://doku.iab.de/fdz/reporte/2025/DR_14-25_EN.pdf",
      "justification": "Administrative longitudinal microdata covering welfare benefit histories in Germany through 2023. Includes information on benefit receipt, employment, income, benefit units, and welfare-related administrative records. Particularly useful for investigating transitions between unemployment and employment, long-term benefit receipt, and the effects of reforms to Germany's basic income support system. The linked document is the dataset's official documentation rather than a direct data download; access to the underlying research data is restricted."
    },
    {
      "title": "Eurostat – European System of Integrated Social Protection Statistics (ESSPROS)",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/social-protection/information-data",
      "justification": "Comprehensive official European statistical framework covering social protection expenditure, financing, benefit recipients, and welfare schemes. Includes Germany and provides annual data spanning the 2020s. Particularly useful for examining Germany's welfare system across multiple policy areas, including pensions, unemployment protection, family benefits, disability support, and social assistance. The landing page provides access to related datasets and methodological information, supporting both national trend analysis and international comparisons."
    },
    {
      "title": "Eurostat – Social Protection Expenditure by Type",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/page/tps00101",
      "justification": "Standardized annual dataset describing the composition of social protection expenditure, including social benefits, administrative costs, and other expenditure categories. Contains observations for Germany covering 2020–2024. Useful for studying whether changes in Germany's welfare expenditure reflect expanded benefit provision, administrative spending, or broader shifts in the organization of social protection."
    }
  ]
}
